97: static void
98: mpl_tk_blit(py::object interp_obj, const char *photo_name,
99:             py::array_t<unsigned char> data, int comp_rule,
100:             std::tuple<int, int, int, int> offset, std::tuple<int, int, int, int> bbox)
101: {
102:     auto interp = convert_voidptr<Tcl_Interp *>(interp_obj);
103: 
104:     Tk_PhotoHandle photo;
105:     if (!(photo = TK_FIND_PHOTO(interp, photo_name))) {
106:         throw py::value_error("Failed to extract Tk_PhotoHandle");
107:     }
108: 
109:     auto data_ptr = data.mutable_unchecked<3>();  // Checks ndim and writeable flag.
110:     if (data.shape(2) != 4) {
111:         throw py::value_error(
112:             "Data pointer must be RGBA; last dimension is {}, not 4"_s.format(
113:                 data.shape(2)));
114:     }
115:     if (data.shape(0) > INT_MAX) {  // Limited by Tk_PhotoPutBlock argument type.
116:         throw std::range_error(
117:             "Height ({}) exceeds maximum allowable size ({})"_s.format(
118:                 data.shape(0), INT_MAX));
119:     }
120:     if (data.shape(1) > INT_MAX / 4) {  // Limited by Tk_PhotoImageBlock.pitch field.
121:         throw std::range_error(
122:             "Width ({}) exceeds maximum allowable size ({})"_s.format(
123:                 data.shape(1), INT_MAX / 4));
124:     }
125:     const auto height = static_cast<int>(data.shape(0));
126:     const auto width = static_cast<int>(data.shape(1));
127:     int x1, x2, y1, y2;
128:     std::tie(x1, x2, y1, y2) = bbox;
129:     if (0 > y1 || y1 > y2 || y2 > height || 0 > x1 || x1 > x2 || x2 > width) {
130:         throw py::value_error("Attempting to draw out of bounds");
131:     }
132:     if (comp_rule != TK_PHOTO_COMPOSITE_OVERLAY && comp_rule != TK_PHOTO_COMPOSITE_SET) {
133:         throw py::value_error("Invalid comp_rule argument");
134:     }
135: 
136:     int put_retval;
137:     Tk_PhotoImageBlock block;
138:     block.pixelPtr = data_ptr.mutable_data(height - y2, x1, 0);
139:     block.width = x2 - x1;
140:     block.height = y2 - y1;
141:     block.pitch = 4 * width;
142:     block.pixelSize = 4;
143:     std::tie(block.offset[0], block.offset[1], block.offset[2], block.offset[3]) = offset;
144:     {
145:         py::gil_scoped_release release;
146:         put_retval = TK_PHOTO_PUT_BLOCK(
147:             interp, photo, &block, x1, height - y2, x2 - x1, y2 - y1, comp_rule);
148:     }
149:     if (put_retval == TCL_ERROR) {
150:         throw std::bad_alloc();
151:     }
152: }
