161:         // This function is a subclassed window procedure, and so is run during
162:         // the Tcl/Tk event loop. Unfortunately, Tkinter has a *second* lock on
163:         // Tcl threading that is not exposed publicly, but is currently taken
164:         // while we're in the window procedure. So while we can take the GIL to
165:         // call Python code, we must not also call *any* Tk code from Python.
166:         // So stay with Tcl calls in C only.
167:         {
168:             // This variable naming must match the name used in
169:             // lib/matplotlib/backends/_backend_tk.py:FigureManagerTk.
170:             std::string var_name("window_dpi");
171:             var_name += std::to_string((unsigned long long)hwnd);
172: 
173:             // X is high word, Y is low word, but they are always equal.
174:             std::string dpi = std::to_string(LOWORD(wParam));
175: 
176:             Tcl_Interp* interp = (Tcl_Interp*)dwRefData;
177:             if (TCL_SETVAR) {
178:                 TCL_SETVAR(interp, var_name.c_str(), dpi.c_str(), 0);
179:             } else if (TCL_SETVAR2) {
180:                 TCL_SETVAR2(interp, var_name.c_str(), NULL, dpi.c_str(), 0);
181:             } else {
182:                 // This should be prevented at import time, and therefore unreachable.
183:                 // But defensively throw just in case.
184:                 throw std::runtime_error("Unable to call Tcl_SetVar or Tcl_SetVar2");
