31: void draw_bitmap(
32:     py::array_t<uint8_t, py::array::c_style> im, FT_Bitmap *bitmap, FT_Int x, FT_Int y)
33: {
34:     auto buf = im.mutable_data(0);
35: 
36:     FT_Int image_width = (FT_Int)im.shape(1);
37:     FT_Int image_height = (FT_Int)im.shape(0);
38:     FT_Int char_width = bitmap->width;
39:     FT_Int char_height = bitmap->rows;
40: 
41:     FT_Int x1 = std::min(std::max(x, 0), image_width);
42:     FT_Int y1 = std::min(std::max(y, 0), image_height);
43:     FT_Int x2 = std::min(std::max(x + char_width, 0), image_width);
44:     FT_Int y2 = std::min(std::max(y + char_height, 0), image_height);
45: 
46:     FT_Int x_start = std::max(0, -x);
47:     FT_Int y_offset = y1 - std::max(0, -y);
48: 
49:     if (bitmap->pixel_mode == FT_PIXEL_MODE_GRAY) {
50:         for (FT_Int i = y1; i < y2; ++i) {
51:             unsigned char *dst = buf + (i * image_width + x1);
52:             unsigned char *src = bitmap->buffer + (((i - y_offset) * bitmap->pitch) + x_start);
53:             for (FT_Int j = x1; j < x2; ++j, ++dst, ++src)
54:                 *dst |= *src;
55:         }
56:     } else if (bitmap->pixel_mode == FT_PIXEL_MODE_MONO) {
57:         for (FT_Int i = y1; i < y2; ++i) {
58:             unsigned char *dst = buf + (i * image_width + x1);
59:             unsigned char *src = bitmap->buffer + ((i - y_offset) * bitmap->pitch);
60:             for (FT_Int j = x1; j < x2; ++j, ++dst) {
61:                 int x = (j - x1 + x_start);
62:                 int val = *(src + (x >> 3)) & (1 << (7 - (x & 0x7)));
63:                 *dst = val ? 255 : *dst;
64:             }
65:         }
66:     } else {
67:         throw std::runtime_error("Unknown pixel mode");
68:     }
69: }
