53: static py::array_t<double>
54: _get_transform_mesh(const py::object& transform, const py::ssize_t *dims)
55: {
56:     /* TODO: Could we get away with float, rather than double, arrays here? */
57: 
58:     /* Given a non-affine transform object, create a mesh that maps
59:     every pixel center in the output image to the input image.  This is used
60:     as a lookup table during the actual resampling. */
61: 
62:     // If attribute doesn't exist, raises Python AttributeError
63:     auto inverse = transform.attr("inverted")();
64: 
65:     py::ssize_t mesh_dims[2] = {dims[0]*dims[1], 2};
66:     py::array_t<double> input_mesh(mesh_dims);
67:     auto p = input_mesh.mutable_data();
68: 
69:     for (auto y = 0; y < dims[0]; ++y) {
70:         for (auto x = 0; x < dims[1]; ++x) {
71:             // The convention for the supplied transform is that pixel centers
72: 	    // are at 0.5, 1.5, 2.5, etc.
73:             *p++ = (double)x + 0.5;
74:             *p++ = (double)y + 0.5;
75:         }
76:     }
77: 
78:     auto output_mesh = inverse.attr("transform")(input_mesh);
79: 
80:     auto output_mesh_array =
81:         py::array_t<double, py::array::c_style | py::array::forcecast>(output_mesh);
82: 
83:     if (output_mesh_array.ndim() != 2) {
84:         throw std::runtime_error(
85:             "Inverse transformed mesh array should be 2D not {}D"_s.format(
86:                 output_mesh_array.ndim()));
87:     }
88: 
89:     return output_mesh_array;
90: }
